"""Client that posts records to the ingestion API."""
import json
import os
import sys
import urllib.error
import urllib.request

# The ingestion endpoint is supplied at runtime, not stored in this repo.
ENDPOINT = (
    os.environ.get("INGESTION_ENDPOINT")
    or os.environ.get("INGESTION_API_URL")
    or ""
)


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        except urllib.error.HTTPError as exc:
            print(f"rejected {record.get('id', '?')}: HTTP {exc.code}", file=sys.stderr)
        except urllib.error.URLError as exc:
            print(f"failed {record.get('id', '?')}: {exc.reason}", file=sys.stderr)
    return accepted


def main():
    if not ENDPOINT:
        print("INGESTION_ENDPOINT is not set", file=sys.stderr)
        return 2

    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
